 function startNew(){const players=chosenPlayers();if(players.length<2){status('اختر لاعبين على الأقل.');return;}playMode='local';onlineSession.stop();state=createMonopolyState(players);recordedWinner='';clearSave();resetBoardFocus();save(state);byId('monoSetup').hidden=true;byId('monoGame').hidden=false;overlayMode='';render();}
