 function ownerColor(ownerId){const i=state.players.findIndex(p=>p.id===ownerId);return TOKEN_COLORS[Math.max(0,i)%TOKEN_COLORS.length];}
 function renderBoard(){const board=byId('monoBoard');if(!board||!state)return;board.querySelectorAll('.mono-space,.mono-moving-token').forEach(n=>n.remove());BOARD.forEach((space,index)=>{const [row,col,edge]=coordinate(index),own=state.ownership[index],tokens=state.players.filter(p=>!p.bankrupt&&p.position===index);const cell=document.createElement('button');cell.type='button';cell.className=`mono-space ${own?'owned':''}`;cell.style.gridRow=String(row);cell.style.gridColumn=String(col);cell.dataset.group=space.group||'';cell.dataset.type=space.type;cell.dataset.edge=edge;cell.dataset.index=String(index);cell.dataset.houses=String(own?.houses||0);cell.setAttribute('aria-label',`${space.name}${space.price?`، السعر ${space.price}`:''}${own?`، ملك ${state.players.find(p=>p.id===own.ownerId)?.name||'لاعب'}`:''}`);if(own)cell.style.setProperty('--owner',ownerColor(own.ownerId));if(space.group)cell.style.setProperty('--band',GROUP_COLOR[space.group]);cell.innerHTML=`${['property','railroad','utility'].includes(space.type)?'<span class="mono-band"></span>':''}<strong>${spaceDisplay(space)}</strong>${own?.houses?`<small>منازل ${digits.format(own.houses)}</small>`:''}<span class="mono-token-row" data-edge="${edge}" aria-hidden="true">${tokens.map(p=>{const i=state.players.findIndex(x=>x.id===p.id);return`<span class="mono-token" data-player-id="${escapeHtml(p.id)}" style="--token:${TOKEN_COLORS[i%TOKEN_COLORS.length]}" title="${escapeHtml(p.name)}">${escapeHtml(p.name.slice(0,1))}</span>`;}).join('')}</span>`;cell.addEventListener('click',()=>showSpace(index));board.appendChild(cell);});}
 function isPhoneLayout(){const width=globalThis.innerWidth||0,height=globalThis.innerHeight||0;return width<=699||(height<=520&&width<=1000);}
 function isTabletPortrait(){const width=globalThis.innerWidth||0,height=globalThis.innerHeight||0;return width>=700&&width<1100&&(globalThis.matchMedia?.('(orientation: portrait)').matches??height>width);}
 function cameraScaleForMove(){const width=globalThis.innerWidth||0;if(isPhoneLayout())return 2.15;if(isTabletPortrait())return 1.9;return width<1400?1.7:1.55;}
 function movementStepDuration(){const width=globalThis.innerWidth||0;if(isPhoneLayout())return 380;if(isTabletPortrait())return 340;return width<1400?320:280;}
 function renderMiniMap(activeIndex,visible=true){const map=byId('monoMiniMap');if(!map)return;map.replaceChildren();BOARD.forEach((space,index)=>{const [row,col]=coordinate(index),cell=document.createElement('span');cell.className=`mono-mini-cell ${index===activeIndex?'active':''}`;cell.style.gridRow=String(row);cell.style.gridColumn=String(col);cell.dataset.group=space.group||'';map.appendChild(cell);});map.hidden=!visible;map.setAttribute('aria-label',`خريطة اللوحة، اللاعب عند ${BOARD[activeIndex]?.name||'البداية'}`);}
 function applyCameraFocus(index,scale){const board=byId('monoBoard'),wrap=byId('monoBoardWrap'),cell=board?.querySelector(`.mono-space[data-index="${index}"]`);if(!board||!wrap||!cell)return;if(scale<=1){board.style.transform='';wrap.classList.remove('is-focused');renderMiniMap(index,false);return;}const x=cell.offsetLeft+cell.offsetWidth/2,y=cell.offsetTop+cell.offsetHeight/2,tx=Math.min(0,Math.max(wrap.clientWidth-board.offsetWidth*scale,wrap.clientWidth/2-x*scale)),ty=Math.min(0,Math.max(wrap.clientHeight-board.offsetHeight*scale,wrap.clientHeight/2-y*scale));board.style.transform=`translate(${tx}px,${ty}px) scale(${scale})`;wrap.classList.add('is-focused');const label=byId('monoFocusLabel');if(label)label.textContent=BOARD[index]?.name||'';renderMiniMap(index,true);}
