 function resetBoardFocus(){movementAnimationId++;movementAnimating=false;zoomOutBoard();}
 function focusMovement(index){const board=byId('monoBoard'),wrap=byId('monoBoardWrap');if(!board||!wrap)return;if(movementFocusIndex!==null)board.querySelector(`.mono-space[data-index="${movementFocusIndex}"]`)?.classList.remove('is-camera-target');movementFocusIndex=index;const cell=board.querySelector(`.mono-space[data-index="${index}"]`);cell?.classList.add('is-camera-path','is-camera-target');const scale=cameraScaleForMove();wrap.classList.add('is-moving');applyCameraFocus(index,scale);}
 function waitForMotion(ms){return new Promise(resolve=>setTimeout(resolve,ms));}
 async function zoomOutBoardTransition(){const board=byId('monoBoard'),wrap=byId('monoBoardWrap');if(!board||!wrap){zoomOutBoard();return;}wrap.classList.remove('is-moving','is-camera-intro');wrap.classList.add('is-camera-outro');board.style.transform='';await waitForMotion(620);wrap.classList.remove('is-camera-outro');zoomOutBoard();}
 async function animateTokenMove(playerId,from,to){if(!Number.isInteger(from)||!Number.isInteger(to)||from===to)return;const board=byId('monoBoard'),destination=board?.querySelector(`.mono-space[data-index="${to}"]`),target=destination&&[...destination.querySelectorAll('.mono-token')].find(node=>node.dataset.playerId===String(playerId));if(!board||!target)return;const reduced=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;const movingPlayer=state?.players.find(player=>player.id===playerId);if(!movingPlayer)return;if(reduced){focusMovement(to);await waitForMotion(1200);return;}const token=document.createElement('span');token.className='mono-moving-token';token.style.setProperty('--token',TOKEN_COLORS[Math.max(0,state.players.indexOf(movingPlayer))%TOKEN_COLORS.length]);token.textContent=String(movingPlayer.name||'?').slice(0,1);target.style.visibility='hidden';board.appendChild(token);const place=index=>{const tile=board.querySelector(`.mono-space[data-index="${index}"]`);if(!tile)return;token.style.left=`${tile.offsetLeft+tile.offsetWidth/2-token.offsetWidth/2}px`;token.style.top=`${tile.offsetTop+tile.offsetHeight/2-token.offsetHeight/2}px`;};const teleport=to===10&&state.log?.includes('السجن'),backward=!teleport&&/ارجع|تراجع/.test(state.lastCard||state.log||'');const distance=teleport?1:backward?(from-to+40)%40:(to-from+40)%40;let index=from;try{place(from);const wrap=byId('monoBoardWrap');wrap?.classList.add('is-camera-intro');focusMovement(from);await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));await waitForMotion(650);wrap?.classList.remove('is-camera-intro');for(let step=1;step<=distance;step++){index=teleport?to:backward?(from-step+40)%40:(from+step)%40;place(index);focusMovement(index);await waitForMotion(movementStepDuration());}await waitForMotion(520);}finally{token.remove();target.style.visibility='';board.querySelectorAll('.mono-space.is-camera-target').forEach(node=>node.classList.remove('is-camera-target'));movementFocusIndex=null;}}
 function renderPlayers(){const host=byId('monoPlayers');if(!host||!state)return;host.innerHTML=state.players.map((p,i)=>`<div class="mono-player-chip ${i===state.turnIndex&&state.status==='playing'?'current':''} ${p.bankrupt?'bankrupt':''}" ${i===state.turnIndex&&state.status==='playing'?'aria-current="true"':''}><strong>${escapeHtml(p.name)}</strong><span>الرصيد ${digits.format(p.cash)}</span><small>${digits.format(Object.values(state.ownership).filter(o=>o.ownerId===p.id).length)} عقار</small></div>`).join('');}
 function setOverlay(title,body,actions){const panel=byId('monoOverlay');if(!panel)return;overlayMode=title;panel.hidden=false;byId('monoControlPanel')?.classList.add('overlay-open');panel.innerHTML=`<h2>${escapeHtml(title)}</h2><div class="mono-overlay-body">${body}</div><div class="mono-overlay-actions">${actions}</div>`;panel.querySelectorAll('[data-action]').forEach(button=>{if(onlineBusy||playMode==='online'&&!canAct(button.dataset.action))button.disabled=true;button.addEventListener('click',()=>handleOverlayAction(button.dataset.action,button.dataset.value));});}
 function hideOverlay(){const panel=byId('monoOverlay');if(panel){panel.hidden=true;byId('monoControlPanel')?.classList.remove('overlay-open');}overlayMode='';}
 function showSpace(index){if(!state||overlayMode||movementAnimating)return;const space=BOARD[index],own=state.ownership[index],owner=state.players.find(p=>p.id===own?.ownerId),detailIcon=spaceIconMarkup(space,'mono-figma-icon mono-deed-icon');const details=space.type==='property'?`<div class="mono-deed mono-figma-property"><span class="mono-deed-band" style="--deed-band:${GROUP_COLOR[space.group]}"></span><strong>${escapeHtml(space.name)} · ${GROUP_LABEL[space.group]||''}</strong><span>السعر ${digits.format(space.price)} · الإيجار الأساسي ${digits.format(space.rent)}</span><span>التطوير ${digits.format(space.build)} · الإيجار يتضاعف عند اكتمال المجموعة</span>${owner?`<span>المالك: ${escapeHtml(owner.name)}</span>`:''}</div>`:`<div class="mono-deed">${detailIcon}<strong>${escapeHtml(space.name)}</strong>${space.amount?`<span>المبلغ ${digits.format(space.amount)}</span>`:''}${space.price?`<span>السعر ${digits.format(space.price)}</span>`:''}${own?`<span>المالك: ${escapeHtml(owner?.name||'لاعب')}</span>`:''}</div>`;setOverlay('بطاقة الخانة',details,`<button class="btn secondary" data-action="focus-space" data-value="${index}">ركّز على الخانة</button><button class="btn secondary" data-action="close">رجوع للوحة</button>`);}
 function renderPlayersAndMain(){const p=state.players[state.turnIndex];if(byId('monoTurn'))byId('monoTurn').textContent=p?.name||'—';if(byId('monoCash'))byId('monoCash').textContent=`الرصيد ${digits.format(p?.cash||0)}`;if(byId('monoLog'))byId('monoLog').textContent=state.log||'';const dice=byId('monoDice');if(dice)dice.textContent=state.dice?`${state.dice[0]}　·　${state.dice[1]}`:'⚄　⚄';}
 function renderActions(){const host=byId('monoActions');if(!host||!state)return;host.innerHTML='';const p=state.players[state.turnIndex];if(state.status==='finished'){host.innerHTML=`<button class="btn primary" data-center-action="restart">جولة جديدة</button><button class="btn secondary" data-center-action="leave">الألعاب</button>`;host.querySelector('[data-center-action=restart]')?.addEventListener('click',()=>{state=null;clearSave();onlineSession.stop();onlineRoom=null;openSetup();});host.querySelector('[data-center-action=leave]')?.addEventListener('click',leave);return;}
   if(state.phase==='roll'){addAction('🎲 ارمِ النرد','roll','primary');if(p.jailed)addAction('ادفع 50 واخرج','jail','secondary');return;}
   if(state.phase==='property'){addAction('شراء الأرض','buy','primary');addAction('تجاوز إلى المزاد','skip','secondary');return;}
   if(state.phase==='auction'){const a=state.auction,turn=state.players[a.nextIndex];addAction(`زايد 10 · دور ${turn?.name||''}`,'bid','primary');addAction('انسحب من المزاد','pass-auction','secondary');return;}
   if(state.phase==='card'){addAction('اقلب البطاقة','card','primary');return;}
   if(state.phase==='end'){addAction('إنهاء الدور','end','primary');}
 }
 function addAction(text,action,kind){const host=byId('monoActions'),button=document.createElement('button');button.className=`btn ${kind}`;button.textContent=text;button.disabled=onlineBusy||playMode==='online'&&!canAct(action);button.addEventListener('click',()=>handleAction(action));host.appendChild(button);}
 function render({deferOutcome=false}={}){if(!state)return;renderPlayers();renderBoard();renderPlayersAndMain();renderActions();if(playMode==='local'&&state.status==='playing')save(state);if(playMode==='local')maybeRecord();if(deferOutcome){hideOverlay();return;}if(state.phase==='property')showPurchase();else if(state.phase==='card')showDrawCard();else if(state.phase==='auction')showAuction();else if(overlayMode&&['إدارة الأملاك','تبادل الأراضي','بطاقة الخانة'].includes(overlayMode)){if(overlayMode==='إدارة الأملاك')showProperties();else if(overlayMode==='تبادل الأراضي')showTrade();}else hideOverlay();}
 function showPurchase(){const i=state.pending.index,s=BOARD[i],p=state.players[state.turnIndex];const html=`<div class="mono-deed mono-figma-property"><span class="mono-deed-band" style="--deed-band:${GROUP_COLOR[s.group]||'#65756b'}"></span><strong>${escapeHtml(s.name)}${s.group?` · ${GROUP_LABEL[s.group]}`:''}</strong><div class="mono-deed-facts"><span>سعر الشراء <b>${digits.format(s.price)}</b></span><span>الإيجار الآن <b>${digits.format(rentFor(state,i)||s.rent||25)}</b></span>${s.type==='property'?`<span>تكلفة التطوير <b>${digits.format(s.build)}</b></span>`:''}<span>رصيد ${escapeHtml(p.name)} <b>${digits.format(p.cash)}</b></span></div></div>`;setOverlay('بطاقة ملكية جديدة',html,`<button class="btn primary" data-action="buy" ${p.cash<s.price?'disabled':''}>شراء الأرض</button><button class="btn secondary" data-action="skip">بدء المزاد</button><button class="btn secondary" data-action="focus-space" data-value="${i}">ركّز على الخانة</button>`);}
 function showDrawCard(){const c=state.pending.card,space=BOARD[state.players[state.turnIndex].position],isChest=space?.type==='chest',title=isChest?'بطاقة صندوق الجماعة':'بطاقة مفاجأة',kind=isChest?'chest':'chance',icon=spaceIconMarkup(space,'mono-figma-icon mono-deed-icon'),effects=[];if(c.cash>0)effects.push(`يضاف إلى الرصيد ${digits.format(c.cash)}`);if(c.cash<0)effects.push(`يخصم من الرصيد ${digits.format(Math.abs(c.cash))}`);if(c.jail)effects.push('انتقل إلى السجن');else if(Number.isInteger(c.moveTo)){effects.push(`انتقل إلى ${BOARD[c.moveTo]?.name||'الخانة المحددة'}`);if(c.collect)effects.push(`استلم ${digits.format(c.collect)}`);}const effectText=effects.length?effects.join(' · '):'يطبق الأثر الموضح على البطاقة';const body=`<article class="mono-figma-action-card" data-kind="${kind}"><header class="mono-figma-action-head">${icon}<strong>${isChest?'صندوق الجماعة':'مفاجأة'}</strong></header><div class="mono-figma-action-rule"></div><p>${escapeHtml(c.text)}</p><small>أثر البطاقة: ${escapeHtml(effectText)}</small></article>`;setOverlay(title,body,'<button class="btn primary" data-action="card">متابعة وتطبيق الأثر</button>');}
 function showAuction(){const a=state.auction,p=state.players[a.nextIndex],s=BOARD[a.index];setOverlay(`مزاد · ${s.name}`,`<div class="mono-deed"><span class="mono-deed-band" style="--deed-band:${GROUP_COLOR[s.group]||'#65756b'}"></span><strong>المزايدة على ${escapeHtml(s.name)}</strong><div class="mono-deed-facts"><span>أعلى عرض <b>${digits.format(a.bid)}</b></span><span>${a.bidderId?`المزايد الأعلى <b>${escapeHtml(state.players.find(x=>x.id===a.bidderId)?.name||'لاعب')}</b>`:'لا توجد عروض بعد'}</span><span>الدور <b>${escapeHtml(p?.name||'لاعب')}</b></span><span>الرصيد <b>${digits.format(p?.cash||0)}</b></span></div></div>`,'<button class="btn primary" data-action="bid">ارفع العرض 10</button><button class="btn secondary" data-action="pass-auction">انسحب من المزاد</button>');}
 function showProperties(){const p=state.players[state.turnIndex],items=BOARD.map((s,i)=>({s,i,o:state.ownership[i]})).filter(x=>x.o?.ownerId===p.id);const body=items.length?`<div class="mono-property-list">${items.map(({s,i,o})=>`<article class="mono-property"><div><strong>${escapeHtml(s.name)}</strong><small>${GROUP_LABEL[s.group]||s.name} · إيجار ${digits.format(rentFor(state,i))}${o.houses?` · ${digits.format(o.houses)} منازل`:''}</small></div><div class="mono-property-actions">${canBuild(state,i)?`<button class="btn secondary" data-action="build" data-value="${i}">تطوير · ${digits.format(s.build)}</button>`:''}<button class="btn secondary" data-action="sell" data-value="${i}">بيع · ${digits.format(Math.floor(s.price/2)+(o.houses||0)*Math.floor((s.build||0)/2))}</button></div></article>`).join('')}</div><p>يُباع العقار بنصف سعره، وتُعاد قيمة نصف التطوير.</p>`:'<p>ما عند اللاعب أملاك للبيع الآن.</p>';setOverlay('إدارة الأملاك',body,'<button class="btn secondary" data-action="trade-open">تبادل الأراضي</button><button class="btn secondary" data-action="close">رجوع للوحة</button>');}
 function showTrade(){const p=state.players[state.turnIndex],owned=BOARD.map((s,i)=>({s,i,o:state.ownership[i]})).filter(x=>x.o?.ownerId===p.id);const others=state.players.filter(x=>x.id!==p.id&&!x.bankrupt);if(!owned.length||!others.length){setOverlay('تبادل الأراضي','<p>يلزم امتلاك أرض ووجود لاعب آخر لإجراء التبادل.</p>','<button class="btn secondary" data-action="manage">رجوع</button>');return;}const body=`<div class="mono-trade-fields"><label>الأرض المعروضة<select id="monoTradeProperty">${owned.map(({s,i})=>`<option value="${i}">${escapeHtml(s.name)}</option>`).join('')}</select></label><label>مع اللاعب<select id="monoTradePlayer">${others.map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.name)}</option>`).join('')}</select></label><label>مبلغ تدفعه<input id="monoTradeOffer" type="number" min="0" step="10" value="0"></label><label>مبلغ تستلمه<input id="monoTradeRequest" type="number" min="0" step="10" value="0"></label></div><p>راجِعوا شروط التبادل معًا قبل التأكيد.</p>`;setOverlay('تبادل الأراضي',body,'<button class="btn primary" data-action="trade-confirm">تأكيد التبادل</button><button class="btn secondary" data-action="manage">رجوع</button>');}
 function canAct(action){if(playMode!=='online')return true;const selfId=onlineSession.snapshot.selfPlayerId;if(!selfId||!state)return false;if(action==='close'||action==='manage'||action==='trade-open'||action==='focus-space')return true;const index=action==='bid'||action==='pass-auction'?state.auction?.nextIndex:state.turnIndex;return state.players[index]?.id===selfId;}
 function handleOverlayAction(action,value){if(action==='close'){hideOverlay();return;}if(action==='focus-space'){focusBoard(Number(value));return;}if(action==='manage'){showProperties();return;}if(action==='trade-open'){showTrade();return;}if(action==='trade-confirm'){const i=Number(byId('monoTradeProperty')?.value),target=byId('monoTradePlayer')?.value,offer=Number(byId('monoTradeOffer')?.value||0),request=Number(byId('monoTradeRequest')?.value||0);act(s=>tradeProperty(s,i,target,offer,request),'trade',{index:i,targetId:target,offerCash:offer,requestCash:request});if(state.phase==='end'){hideOverlay();}return;}if(action==='sell'){act(s=>sellProperty(s,Number(value)),'sell',{index:Number(value)});showProperties();return;}if(action==='build'){act(s=>buildHouse(s,Number(value)),'build',{index:Number(value)});showProperties();return;}handleAction(action);}
 function handleAction(action){if(!state)return;if(action==='roll'){const dice=byId('monoDice');if(dice){dice.classList.remove('rolling');void dice.offsetWidth;dice.classList.add('rolling');dice.addEventListener('animationend',()=>dice.classList.remove('rolling'),{once:true});}act(rollDice,'roll');}else if(action==='jail')act(payJail,'jail');else if(action==='buy')act(buyProperty,'buy');else if(action==='skip')act(skipProperty,'skip');else if(action==='bid')act(bidAuction,'bid');else if(action==='pass-auction')act(passAuction,'pass-auction');else if(action==='card')act(drawCard,'card');else if(action==='build')act(buildHouse,'build');else if(action==='end')act(endTurn,'end');}
 async function act(fn,remoteType=null,payload={}){if(!state||onlineBusy||movementAnimating)return;if(playMode==='online'){onlineBusy=true;if(byId('monoLog'))byId('monoLog').textContent='جارٍ مزامنة الحركة…';renderActions();try{await onlineSession.submit(remoteType,payload);}catch(error){handleOnlineError(error);}finally{onlineBusy=false;if(state&&!movementAnimating)render();}return;}const actor=state.players[state.turnIndex],from=actor?.position,next=fn(state);if(next!==state)state=next;const moved=actor&&state.players.find(player=>player.id===actor.id),to=moved?.position;if(Number.isInteger(from)&&Number.isInteger(to)&&from!==to){resetBoardFocus();movementAnimating=true;const animationId=++movementAnimationId;render({deferOutcome:true});if(byId('monoLog'))byId('monoLog').textContent=`يتحرك ${actor.name} إلى ${BOARD[to].name}`;await animateTokenMove(actor.id,from,to);if(animationId!==movementAnimationId)return;movementAnimating=false;render();await zoomOutBoardTransition();return;}render();}
 function maybeRecord(){if(state?.status!=='finished'||!state.winnerId||recordedWinner===state.winnerId)return;recordedWinner=state.winnerId;clearSave();void gameHistoryService.recordGameResult({gameId:'family-monopoly',gameVersion:2,startedAt:state.startedAt||new Date().toISOString(),endedAt:new Date().toISOString(),winnerIds:[state.winnerId],players:state.players.map((p,i)=>({learnerId:p.id,displayName:p.name,seat:i,score:p.cash,outcome:p.id===state.winnerId?'win':'loss',details:{properties:Object.values(state.ownership).filter(o=>o.ownerId===p.id).length}})),details:{board:'knowledge-monopoly-classic-40'}}).catch(()=>null);}
 function openSetup(){ensureMonopolyShell();state=null;onlineBusy=false;onlineRoom=null;onlineSession.stop();overlayMode='';resetBoardFocus();hideOverlay();document.body.classList.add('monopoly-game-mode','games-mode');byId('monoSetup').hidden=false;byId('monoGame').hidden=true;status('');renderPicker();renderOnlinePicker();document.querySelectorAll('[data-mono-mode]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.monoMode===playMode)));byId('monoLocalSetup').hidden=playMode!=='local';byId('monoOnlineSetup').hidden=playMode!=='online';show('monopolyGameView');}
 function leave({navigate=true}={}){state=null;onlineSession.stop();onlineRoom=null;hideOverlay();document.body.classList.remove('monopoly-game-mode');if(navigate){show('gamesHomeView');onBack?.();}}
 function bind(){if(bound)return;bound=true;ensureMonopolyShell();globalThis.addEventListener?.('pageshow',event=>{if(event.persisted&&document.getElementById('monopolyGameView')?.classList.contains('active'))openSetup();});byId('monoBack')?.addEventListener('click',leave);byId('monoStart')?.addEventListener('click',startNew);byId('monoResume')?.addEventListener('click',resume);byId('monoManage')?.addEventListener('click',()=>showProperties());byId('monoFocusPlayer')?.addEventListener('click',focusActivePlayer);byId('monoBoardOverview')?.addEventListener('click',resetBoardFocus);globalThis.addEventListener?.('resize',resetBoardFocus,{passive:true});document.querySelectorAll('[data-mono-mode]').forEach(button=>button.addEventListener('click',()=>setMode(button.dataset.monoMode)));byId('monoCreateRoom')?.addEventListener('click',createOnlineRoom);byId('monoJoinRoom')?.addEventListener('click',joinOnlineRoom);byId('monoResumeRoom')?.addEventListener('click',resumeOnlineRoom);byId('monoRoomStart')?.addEventListener('click',startOnlineRoom);byId('monoRestart')?.addEventListener('click',()=>{if(confirm('بدء جولة جديدة؟')){state=null;clearSave();onlineSession.stop();onlineRoom=null;overlayMode='';openSetup();}});byId('monoGuestToggle')?.addEventListener('change',()=>status(''));byId('monoGuestName')?.addEventListener('input',()=>{const guest=byId('monoPlayerPicker')?.querySelector('[data-mono-player="guest"]');if(guest)guest.textContent=byId('monoGuestName').value;});}
 return Object.freeze({start(){ensureMonopolyShell();bind();openSetup();},leave});
